namespace Meridian.Infrastructure;

public static class DependencyInjection
{
    public const string ConnectionStringName = "Meridian";
    public const string DefaultConnectionString = "Data Source=meridian.db";
    public const string OpenRouterReferer = "http://localhost";
    public const string OpenRouterTitle = "meridian-triage";

    /// <param name="services">The service collection.</param>
    /// <param name="openRouterApiKey">
    /// Supplies the OpenRouter key. Defaults to the <c>OPENROUTER_API_KEY</c> environment variable; tests pass their own.
    /// </param>
    public static IServiceCollection AddMeridianInfrastructure(
        this IServiceCollection services,
        Func<string?>? openRouterApiKey = null)
    {
        var readApiKey = openRouterApiKey ?? TriageOptions.ReadApiKey;

        services.AddDbContext<MeridianDbContext>((sp, options) =>
        {
            var configuration = sp.GetRequiredService<IConfiguration>();
            var connectionString = configuration.GetConnectionString(ConnectionStringName) ?? DefaultConnectionString;
            options.UseSqlite(connectionString);
        });

        services.AddScoped<IJobRepository, JobRepository>();
        services.AddScoped<IPropertyRepository, PropertyRepository>();
        services.AddScoped<IContractorRepository, ContractorRepository>();
        services.AddScoped<IUnitOfWork, EfUnitOfWork>();
        services.AddScoped<IOutbox, SimulatedOutbox>();
        services.AddSingleton<IClock, SystemClock>();

        // AD-1: the recorded-response stub is the default; OpenRouter only when the key is set (or Triage:Provider says so).
        services.AddHttpClient(OpenRouterTriageModel.HttpClientName, (sp, client) =>
            {
                var options = TriageOptions.From(sp.GetRequiredService<IConfiguration>());
                client.BaseAddress = new Uri(options.OpenRouterBaseUrl.TrimEnd('/') + "/");
                var key = readApiKey();
                if (key is not null)
                {
                    client.DefaultRequestHeaders.TryAddWithoutValidation("Authorization", $"Bearer {key}");
                }

                client.DefaultRequestHeaders.TryAddWithoutValidation("HTTP-Referer", OpenRouterReferer);
                client.DefaultRequestHeaders.TryAddWithoutValidation("X-Title", OpenRouterTitle);
            })
            .RedactLoggedHeaders(_ => true);

        services.AddSingleton<ITriageModel>(sp =>
        {
            var options = TriageOptions.From(sp.GetRequiredService<IConfiguration>());
            if (!options.UsesOpenRouter(readApiKey()))
            {
                return StubTriageModel.FromDirectory(StubTriageModel.DefaultDirectory);
            }

            return new OpenRouterTriageModel(
                sp.GetRequiredService<IHttpClientFactory>(),
                options.Model,
                OpenRouterTriageModel.LoadSystemPromptVersion(options.PromptVersion),
                sp.GetService<ILogger<OpenRouterTriageModel>>(),
                options.PromptVersion);
        });
        return services;
    }

    /// <summary>
    /// Applies pending EF migrations (creates the database on first run), then seeds buildings and properties, and
    /// contractors and their assignments, each when there are none (<see cref="SeedData"/>).
    /// </summary>
    public static async Task MigrateMeridianDatabaseAsync(this IServiceProvider services, CancellationToken cancellationToken = default)
    {
        await using var scope = services.CreateAsyncScope();
        var db = scope.ServiceProvider.GetRequiredService<MeridianDbContext>();
        await db.Database.MigrateAsync(cancellationToken);
        await SeedData.EnsureSeededAsync(db, cancellationToken);
    }
}
namespace Meridian.Domain.Messages;

/// <summary>
/// A tenant message, stored exactly as received (RULE-9) and only once. The text is never altered. One message can
/// make several jobs (one per issue), and one job can have several messages (the first plus follow-ups).
/// </summary>
public sealed class Message
{
    private Message()
    {
        Sender = string.Empty;
        Text = string.Empty;
    }

    public Guid Id { get; private set; }

    public string Sender { get; private set; }

    public string Text { get; private set; }

    public DateTime ReceivedAtUtc { get; private set; }

    public static Message Receive(string sender, string text, DateTime receivedAtUtc)
    {
        if (string.IsNullOrWhiteSpace(sender))
        {
            throw new ArgumentException("Sender is required.", nameof(sender));
        }

        if (string.IsNullOrWhiteSpace(text))
        {
            throw new ArgumentException("Message text is required.", nameof(text));
        }

        Guards.RequireUtc(receivedAtUtc, nameof(receivedAtUtc));

        return new Message
        {
            Id = Guid.NewGuid(),
            Sender = sender,
            Text = text,
            ReceivedAtUtc = receivedAtUtc,
        };
    }
}
namespace Meridian.Domain.Properties;

/// <summary>
/// A building Meridian manages, e.g. <c>22 Pemberton Road</c> or <c>Alder Court</c>. A name that starts with a
/// house number (<c>22 Pemberton Road</c>) is matched only together with that number (AD-13).
/// </summary>
public sealed class Building
{
    private readonly List<Property> _properties = new();

    private Building()
    {
        Name = string.Empty;
    }

    public Guid Id { get; private set; }

    /// <summary>The building's address as Meridian writes it, e.g. <c>22 Pemberton Road</c>.</summary>
    public string Name { get; private set; }

    public IReadOnlyList<Property> Properties => _properties;

    public static Building Create(Guid id, string name)
    {
        if (id == Guid.Empty)
        {
            throw new ArgumentException("An id is required.", nameof(id));
        }

        if (string.IsNullOrWhiteSpace(name))
        {
            throw new ArgumentException("A building name is required.", nameof(name));
        }

        return new Building { Id = id, Name = name.Trim() };
    }

    /// <summary>Adds the whole building as one property (a house), with no unit.</summary>
    public Property AddWholeBuilding(Guid id) => Add(Property.Create(id, Id, null, Name));

    /// <summary>Adds a flat, e.g. unit <c>4</c> shown as <c>Flat 4, 22 Pemberton Road</c>.</summary>
    /// <param name="name">How the flat is shown; defaults to <c>Flat {unit}, {building}</c>.</param>
    public Property AddFlat(Guid id, string unit, string? name = null)
    {
        if (string.IsNullOrWhiteSpace(unit))
        {
            throw new ArgumentException("A unit is required.", nameof(unit));
        }

        return Add(Property.Create(id, Id, unit.Trim(), name ?? $"Flat {unit.Trim()}, {Name}"));
    }

    private Property Add(Property property)
    {
        if (_properties.Any(p => p.Unit is null) || (property.Unit is null && _properties.Count > 0))
        {
            throw new InvalidOperationException("A whole-building property cannot share a building with flats.");
        }

        if (property.Unit is not null
            && _properties.Any(p => string.Equals(p.Unit, property.Unit, StringComparison.OrdinalIgnoreCase)))
        {
            throw new InvalidOperationException($"Unit {property.Unit} already exists in {Name}.");
        }

        property.SetBuilding(this);
        _properties.Add(property);
        return property;
    }
}
